INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (26, 3, '函数 f(x) 在 x=a 处连续且存在导数，那么 f(x) 在 x=a 处一定可导。', '对|错', 'F', '连续不可推存在导数， |x| 在 0 处连续但不可导。', 1, (SELECT id FROM knowledge_point WHERE course_id=26 AND point_name='函数的概念及常见函数' LIMIT 1), 2.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (26, 4, '求 f(x) = x^3 + 2x 在 x=1 处的导数值。', NULL, '5', 'f''(x) = 3x^2 + 2，代入 x=1 得 5。', 1, (SELECT id FROM knowledge_point WHERE course_id=26 AND point_name='导数' LIMIT 1), 2.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (26, 5, '简述函数在一点处可导与连续的关系，并举一例说明。', NULL, '可导必连续，反之不成立。例如 f(x)=|x| 在 x=0 连续但不可导。', '可导函数在该点必连续，连续函数在该点不一定可导。', 2, (SELECT id FROM knowledge_point WHERE course_id=26 AND point_name='函数的概念及常见函数' LIMIT 1), 5.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (27, 3, '两个 3 阶矩阵相乘，结果的秩一定不大于其中任一个矩阵的秩。', '对|错', 'T', '秩不超过因数矩阵的秩。', 1, (SELECT id FROM knowledge_point WHERE course_id=27 AND point_name='矩阵及其运算' LIMIT 1), 2.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (27, 4, '已知 2 阶行列式 |a b; c d| = 5，求 |2a 2b; 2c 2d| 的值。', NULL, '20', '行列式的每一行提出因子 2，2^2 × 5 = 20。', 1, (SELECT id FROM knowledge_point WHERE course_id=27 AND point_name='行列式' LIMIT 1), 2.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (27, 5, '解释 n 维向量点积的几何意义。', NULL, '点积 = 两向量模的乘积 × 夹角余弦值。', 'a·b = |a||b|cosθ。', 2, (SELECT id FROM knowledge_point WHERE course_id=27 AND point_name='向量的内积' LIMIT 1), 5.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (28, 3, '互斥事件（P(AB)=0）一定是相互独立的。', '对|错', 'F', '互斥事件不满足 P(AB)=P(A)P(B)。', 1, (SELECT id FROM knowledge_point WHERE course_id=28 AND point_name='随机事件与概率' LIMIT 1), 2.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (28, 4, '泊松分布参数 λ 的概率解释。', NULL, '单位时间或单位面积内事件发生的平均次数', '泊松分布刻画单位区间事件发生的平均次数 λ。', 1, (SELECT id FROM knowledge_point WHERE course_id=28 AND point_name='随机变量及分布' LIMIT 1), 2.0, 1);
INSERT INTO question (course_id, question_type, content, options, answer, analysis, difficulty, knowledge_id, score, creator_id) VALUES (28, 5, '写出条件概率 P(B|A) 的定义，并说明适用条件。', NULL, 'P(B|A)=P(AB)/P(A)，需 P(A)>0。', '条件概率 = 联事件概率 / 给定事件概率。', 2, (SELECT id FROM knowledge_point WHERE course_id=28 AND point_name='随机事件与概率' LIMIT 1), 5.0, 1);
